    num1 = 24
    num2 = 26
    factors_of_num1 = set()
    factors_of_num2 = set()
    for i in range(1, int(math.sqrt(num1)) + 1):
        if num1 % i == 0:
            factors_of_num1.add(i)
            factors_of_num1.add(num1 // i)
    for i in range(1, int(math.sqrt(num2)) + 1):
