        result = 'A'
    elif math.fabs(time - 54) < 1e-4:
        result = 'B'
    elif math.fabs(time - 40) < 1e-4:
        result = 'C'
    elif math.fabs(time - 36) < 1e-4:
        result = 'D'
    elif math.fabs(time - 31) < 1e-4:
        result = 'E'
    return result

