def solution():
    """how many of the positive factors of 36 are not factors of 72 () A ) 0 , B ) 3 , C ) 4 , D ) 5 , E ) 1"""
    import math
    options = [0, 3, 4, 5, 1]
    num1 = 36
    num2 = 72
    factors_of_num1 = set()
    factors_of_num2 = set()
    for i in range(1, int(math.sqrt(num1)) + 1):
        if num1 % i == 0:
            factors_of_num1.add(i)
            factors_of_num1.add(num1 // i)
    for i in range(1, int(math.sqrt(num2)) + 1):
        if num2 % i == 0:
            factors_of_num2.add(i)
            factors_of_num2.add(num2 // i)
    common_factors = factors_of_num1.intersection(factors_of_num2)
    result = len(factors_of_num1) - len(common_factors)
    return chr(ord('A') + options.index(result))

