def solution():
    """find the number of elements in the power set of { 1,2 }
    ()
    A ) 4 , B ) 0 , C ) 2 , D ) 3 , E ) 5"""
    a = {1, 2}
    power_set = set()
    for i in range(2 ** len(a)):
        subset = set()
        for j, item in enumerate(a):
            if i & (1 << j):
                subset.add(item)
        power_set.add(frozenset(subset))
    result = len(power_set)
    if result == 4:
        return 'A'
    elif result == 0:
        return 'B'
    elif result == 2:
        return 'C'
    elif result == 3:
        return 'D'
    elif result == 5:
        return 'E'

