    num2 = 45
    factors_of_num1 = set()
    factors_of_num2 = set()
    for i in range(1, int(math.sqrt(num1)) + 1):
        if num1 % i == 0:
            factors_of_num1.add(i)
            factors_of_num1.add(num1 // i)
    for i in range(1, int(math.sqrt(num2)) + 1):
        if num2 % i == 0:
            factors_of_num2.add(i)
            factors_of_num2.add(num2 // i)
    common_factors = factors_of_num1.intersection(factors_of_num2)
